        const dialog = screen.getByRole('dialog')

        expect(dialog).toHaveStyle({
            borderRadius: '0px', height: '100vh', left: '0px', margin: '0px', maxHeight: 'none', maxWidth: 'none',
            top: '0px', width: '100vw',
        })
        expect(screen.queryByRole('separator', { name: /Resize action popup/u })).not.toBeInTheDocument()
        expect(screen.queryByRole('button', { name: /Expand upward|Collapse downward/u })).not.toBeInTheDocument()
        expect(screen.getByTestId('action-popup-scroll-body')).toHaveStyle({ minHeight: '0', overflow: 'auto' })
        expect(screen.getByRole('button', { name: 'Run' })).toBeInTheDocument()

        const actionGroup = screen.getByRole('group', { name: 'Actions' })
        fireEvent.click(within(actionGroup).getByRole('button', { name: 'Second action' }))
        expect(within(actionGroup).getByRole('button', { name: 'Second action' })).toHaveAttribute('aria-pressed', 'true')
        fireEvent.click(screen.getByRole('button', { name: 'Close' }))

        expect(onClose).toHaveBeenCalledOnce()
        expect(getStoredValue).not.toHaveBeenCalledWith(CARD_RUN_POPUP_SIZE_STORAGE_KEY)
        expect(setStoredValue).not.toHaveBeenCalledWith(CARD_RUN_POPUP_SIZE_STORAGE_KEY, expect.any(String))
        expect(window.localStorage.getItem(CARD_RUN_POPUP_SIZE_STORAGE_KEY)).toBe(storedSize)
    })

    it('keeps project conversation controls usable in the mobile layout', () => {
        setMobileBreakpoint(true)
        actionService.loadFromFiles([
            file(agentDefinition('review', { appliesTo: { kind: 'project' }, label: 'Review project' })),
        ])

        renderPopup({ kind: 'project' })

        expect(screen.getByRole('dialog')).toHaveStyle({ height: '100vh', left: '0px', top: '0px', width: '100vw' })
        expect(screen.getByRole('combobox', { name: 'Conversation history' })).toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'Send' })).toBeInTheDocument()
        expect(screen.queryByRole('separator', { name: /Resize action popup/u })).not.toBeInTheDocument()
    })

    it('expands upward and restores the anchored size after collapse', () => {
        const consoleError = vi.spyOn(console, 'error').mockImplementation(() => undefined)
        const { onClose } = renderPopup()
        const dialog = screen.getByRole('dialog')

        fireEvent.click(screen.getByRole('button', { name: 'Expand upward' }))
        expect(dialog.style.height).toBe('100vh')

        fireEvent.click(screen.getByRole('button', { name: 'Collapse downward' }))
        expect(dialog.style.height).toBe('450px')

        fireEvent.click(screen.getByRole('button', { name: 'Expand upward' }))
        fireEvent.click(screen.getByRole('button', { name: 'Close' }))

        expect(onClose).toHaveBeenCalledOnce()
        expect(consoleError).not.toHaveBeenCalled()
    })
})

import { ThemeProvider, type PaletteMode } from '@mui/material'
import { cleanup, render, screen, within } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { ActionContext } from '../../../../data/action_context'
import { BUILTIN_CUSTOM_PROMPT, type ActionDefinition } from '../../../../data/action_types'
import type { ActiveActionRun } from '../../../../services/actions/action_run_registry'
import { createAppTheme } from '../../../../theme/app_theme'
import { ActionSelector } from './action_selector'

const activeRuns = vi.hoisted(() => ({ value: [] as ActiveActionRun[] }))

vi.mock('../../../hooks/use_action_runs', () => ({useActiveActionRunsForContext: () => activeRuns.value}))

const context: ActionContext = { file: 'design/F-105.md', kind: 'card', state: 'design', type: 'feature' }
const actions: ActionDefinition[] = [
    { ...BUILTIN_CUSTOM_PROMPT, id: 'selected', label: 'Selected action' },
    { ...BUILTIN_CUSTOM_PROMPT, id: 'unselected', label: 'Unselected action' },
]

function renderSelector(mode: PaletteMode) {
    const theme = createAppTheme(mode)
    activeRuns.value = actions.map(({ id }) => ({ rootActionId: id, runId: `${id}-run`, status: 'waitingForInput' }))
    render(
        <ThemeProvider theme={theme}>
            <ActionSelector
                allowAdd
                actions={actions}
                adding={false}
                context={context}
                onAdd={vi.fn()}
                onSelect={vi.fn()}
                selectedAction={actions[0]}
            />
        </ThemeProvider>,
    )

    return theme
}

describe('ActionSelector', () => {
    afterEach(() => {
        activeRuns.value = []
        cleanup()
    })

    it.each(['light', 'dark'] as const)('keeps waiting borders visible for selected and unselected actions in %s mode', (mode) => {
        const theme = renderSelector(mode)
        const actionGroup = within(screen.getByRole('group', { name: 'Actions' }))
        const selectedButton = actionGroup.getByRole('button', { name: /Selected action.*Agent is waiting for input/u })
        const unselectedButton = actionGroup.getByRole('button', { name: /Unselected action.*Agent is waiting for input/u })

        expect(selectedButton).toHaveAttribute('aria-pressed', 'true')
        expect(unselectedButton).toHaveAttribute('aria-pressed', 'false')
        expect(selectedButton).toHaveStyle({ borderColor: theme.palette.warning.main })
        expect(unselectedButton).toHaveStyle({ borderColor: theme.palette.warning.main })
        expect(within(selectedButton).getByTestId('HelpCircleOutlineIcon')).toBeInTheDocument()
        expect(within(selectedButton).queryByTestId('PlayIcon')).not.toBeInTheDocument()
    })
})
